SELECT t.id, t.alarm_transfer_name AS alarmTransferName, t.tenant_id AS tenantId, t.creator, t.create_time AS createTime, t.modifier, t.update_time AS updateTime, t.industry_code AS industryCode FROM vm_alarm_transfer_config t WHERE t.delete_flag = '0' ${dataScope}
AND t.tenant_id = #{tenantId}
AND t.industry_code = #{industryCode}
AND t.alarm_transfer_name LIKE CONCAT('%', #{alarmTransferName}, '%')
AND t.creator LIKE CONCAT('%', #{creator}, '%')
AND t.modifier LIKE CONCAT('%', #{modifier}, '%')
AND t.create_time >= #{createTimeStart} AND t.create_time <= #{createTimeEnd}
AND t.update_time >= #{updateTimeStart} AND t.update_time <= #{updateTimeEnd}
order by t.create_time
desc
asc
order by t.update_time
desc
asc
order by t.create_time desc

